#[test]
fn sti_fixtures_preserve_shadow_and_cover_the_cpl_iopl_matrix() {
    assert_eq!(STI_FIXTURES.len(), 16);
    for fixture in STI_FIXTURES {
        let (input, result) = run(fixture, "interpreter", 0);
        assert_eq!(input.fixture.profile, od_testkit::v2::Profile::LongStiV1);
        let cpl: u8 = input.fixture.cli_cpl.unwrap().into();
        let iopl = ((input.fixture.initial_state.rflags.get() >> 12) & 3) as u8;
        if cpl <= iopl {
            assert!(matches!(result.outcome, Outcome::StopAddress {}));
            assert_eq!(count(&result), 1);
            let observed = snapshot(&result);
            assert_eq!(
                observed.state.rip,
                HexU64(input.fixture.initial_state.rip.get() + 1)
            );
            assert_ne!(observed.state.rflags.get() & (1 << 9), 0);
            assert_eq!(
                observed.state.sti_shadow,
                Some(od_testkit::v2::StiShadowSnapshot::Blocking)
            );
            assert_eq!(
                od_testkit::v2::compare(&input, &result, &result).unwrap(),
                Vec::<String>::new()
            );

            let mut tampered = result.clone();
            if let Observation::Available { value } = &mut tampered.snapshot {
                value.state.sti_shadow = Some(od_testkit::v2::StiShadowSnapshot::Clear);
            }
            assert!(
                od_testkit::v2::compare(&input, &result, &tampered)
                    .unwrap()
                    .contains(&"state.sti_shadow".to_owned())
            );
            for bit in [9, 12] {
                let mut flags_tampered = result.clone();
                if let Observation::Available { value } = &mut flags_tampered.snapshot {
                    value.state.rflags = HexU64(value.state.rflags.get() ^ (1 << bit));
                    if bit == 9 {
                        value.state.sti_shadow = Some(od_testkit::v2::StiShadowSnapshot::Clear);
                    }
                }
                assert!(
                    od_testkit::v2::compare(&input, &result, &flags_tampered)
                        .unwrap()
                        .contains(&"rflags".to_owned())
                );
            }
        } else {
            assert!(matches!(result.outcome, Outcome::Exception {}));
            assert_eq!(count(&result), 0);
            assert_eq!(snapshot(&result).state, input.fixture.initial_state);
        }
    }
}

#[test]
fn hlt_fixtures_preserve_activity_and_enforce_cpl_zero() {
    assert_eq!(HLT_FIXTURES.len(), 16);
    let mut halted = 0;
    let mut faults = 0;
    for fixture in HLT_FIXTURES {
        let (input, result) = run(fixture, "interpreter", 0);
        assert_eq!(input.fixture.profile, od_testkit::v2::Profile::LongHltV1);
        let cpl: u8 = input.fixture.cli_cpl.unwrap().into();
        let observed = snapshot(&result);
        if cpl == 0 {
            halted += 1;
            assert!(matches!(result.outcome, Outcome::Halted {}));
            assert_eq!(count(&result), 1);
            assert_eq!(
                observed.state.rip,
                HexU64(input.fixture.initial_state.rip.get() + 1)
            );
            assert_eq!(
                observed.state.activity,
                Some(od_testkit::v2::CpuActivitySnapshot::Halted)
            );
            assert_eq!(
                observed.state.sti_shadow,
                Some(od_testkit::v2::StiShadowSnapshot::Clear)
            );
            assert_eq!(
                od_testkit::v2::compare(&input, &result, &result).unwrap(),
                Vec::<String>::new()
            );
            let mut tampered = result.clone();
            if let Observation::Available { value } = &mut tampered.snapshot {
                value.state.activity = Some(od_testkit::v2::CpuActivitySnapshot::Running);
            }
            assert!(
                od_testkit::v2::compare(&input, &result, &tampered)
                    .unwrap()
                    .contains(&"state.activity".to_owned())
            );
        } else {
            faults += 1;
            assert!(matches!(result.outcome, Outcome::Exception {}));
            assert_eq!(count(&result), 0);
            assert_eq!(observed.state, input.fixture.initial_state);
        }
    }
    assert_eq!((halted, faults), (4, 12));

    for fixture in HLT_COMPOUND_FIXTURES {
        let (input, result) = run(fixture, "interpreter", 0);
        assert!(matches!(result.outcome, Outcome::Halted {}));
        assert_eq!(count(&result), input.fixture.instruction_budget);
        assert_eq!(
            snapshot(&result).state.activity,
            Some(od_testkit::v2::CpuActivitySnapshot::Halted)
        );
        assert_eq!(
            snapshot(&result).state.sti_shadow,
            Some(od_testkit::v2::StiShadowSnapshot::Clear)
        );
        assert_eq!(
            od_testkit::v2::compare(&input, &result, &result).unwrap(),
            Vec::<String>::new()
        );
    }
    let (_, jit) = run(HLT_FIXTURES[0], "jit", 4);
    assert!(matches!(jit.outcome, Outcome::Unsupported { .. }));

    let mut invalid = Fixture::from_json(HLT_FIXTURES[0]).unwrap().fixture;
    invalid.initial_state.activity = Some(od_testkit::v2::CpuActivitySnapshot::Halted);
    invalid.initial_state.sti_shadow = Some(od_testkit::v2::StiShadowSnapshot::Blocking);
    assert!(invalid.to_json().is_err());
}

#[test]
fn iretq_cpl0_fixtures_restore_frame_and_both_descriptor_caches() {
    for (if_enabled, iopl) in [(0u64, 0u64), (0, 3), (1, 0), (1, 3)] {
        let bytes: &[u8] = match (if_enabled, iopl) {
            (0, 0) => include_bytes!(
                "../../../tests/fixtures/x86/stage2/s2_27k_iretq_if0_iopl0.case.json"
            ),
            (0, 3) => include_bytes!(
                "../../../tests/fixtures/x86/stage2/s2_27k_iretq_if0_iopl3.case.json"
            ),
            (1, 0) => include_bytes!(
                "../../../tests/fixtures/x86/stage2/s2_27k_iretq_if1_iopl0.case.json"
            ),
            _ => include_bytes!(
                "../../../tests/fixtures/x86/stage2/s2_27k_iretq_if1_iopl3.case.json"
            ),
        };
        let (input, result) = run(bytes, "interpreter", 0);
        assert!(matches!(result.outcome, Outcome::StopAddress {}));
        assert_eq!(count(&result), 1);
        let observed = snapshot(&result);
        let frame = od_testkit::v2::decode_bytes(
            &input
                .fixture
                .memory
                .iter()
                .find(|r| r.region_id == "frame")
                .unwrap()
                .initial_bytes_hex,
        )
        .unwrap();
        let saved =
            |slot: usize| u64::from_le_bytes(frame[slot * 8..slot * 8 + 8].try_into().unwrap());
        assert_eq!(observed.state.rip, HexU64(saved(0)));
        assert_eq!(
            observed.state.cs_selector,
            Some(HexU64(saved(1) as u16 as u64))
        );
        assert_eq!(observed.state.rflags, HexU64(saved(2)));
        assert_eq!(observed.state.gpr[4], HexU64(saved(3)));
        assert_eq!(
            observed.state.ss_selector,
            Some(HexU64(saved(4) as u16 as u64))
        );
        assert_eq!(observed.state.cs_cache_access, Some(HexU64(0x9b)));
        assert_eq!(observed.state.cs_cache_flags, Some(HexU64(0xa)));
        assert_eq!(observed.state.ss_cache_access, Some(HexU64(0x93)));
        assert_eq!(observed.state.ss_cache_flags, Some(HexU64(0xc)));
        assert_eq!(
            observed.state.activity,
            Some(od_testkit::v2::CpuActivitySnapshot::Running)
        );
        assert_eq!(
            observed.state.sti_shadow,
            Some(od_testkit::v2::StiShadowSnapshot::Clear)
        );
        assert_eq!(
            observed.rflags_defined,
            HexU64(od_testkit::v2::INTEGER_FLAGS)
        );
    }
    let fixture =
        include_bytes!("../../../tests/fixtures/x86/stage2/s2_27k_iretq_if1_iopl3.case.json");
    for engine in ["jit", "native"] {
        let (_, result) = run(fixture, engine, 4);
        assert!(matches!(result.outcome, Outcome::Unsupported { .. }));
    }
}

#[test]
fn lretq_cpl0_fixtures_consume_two_qwords_and_preserve_ss() {
    let cases: [&[u8]; 4] = [
        include_bytes!("../../../tests/fixtures/x86/stage2/s2_27l_lretq_if0_iopl0.case.json"),
        include_bytes!("../../../tests/fixtures/x86/stage2/s2_27l_lretq_if0_iopl3.case.json"),
        include_bytes!("../../../tests/fixtures/x86/stage2/s2_27l_lretq_if1_iopl0.case.json"),
        include_bytes!("../../../tests/fixtures/x86/stage2/s2_27l_lretq_if1_iopl3.case.json"),
    ];
    for fixture in cases {
        let (input, result) = run(fixture, "interpreter", 0);
        assert!(matches!(result.outcome, Outcome::StopAddress {}));
        assert_eq!(count(&result), 1);
        let observed = snapshot(&result);
        let frame = od_testkit::v2::decode_bytes(
            &input
                .fixture
                .memory
                .iter()
                .find(|r| r.region_id == "frame")
                .unwrap()
                .initial_bytes_hex,
        )
        .unwrap();
        let target = u64::from_le_bytes(frame[0..8].try_into().unwrap());
        let selector = u64::from_le_bytes(frame[8..16].try_into().unwrap()) as u16;
        assert_eq!(observed.state.rip, HexU64(target));
        assert_eq!(observed.state.gpr[4], HexU64(0x0030_0010));
        assert_eq!(observed.state.rflags, input.fixture.initial_state.rflags);
        assert_eq!(observed.state.cs_selector, Some(HexU64(selector as u64)));
        assert_eq!(observed.state.cs_cache_access, Some(HexU64(0x9b)));
        assert_eq!(observed.state.cs_cache_flags, Some(HexU64(0xa)));
        assert_eq!(
            observed.state.ss_selector,
            input.fixture.initial_state.ss_selector
        );
        assert_eq!(
            observed.state.ss_cache_access,
            input.fixture.initial_state.ss_cache_access
        );
        assert_eq!(
            observed.state.ss_cache_flags,
            input.fixture.initial_state.ss_cache_flags
        );
        assert_eq!(
            observed.rflags_defined,
            HexU64(od_testkit::v2::INTEGER_FLAGS)
        );
    }
    for engine in ["jit", "native"] {
        let (_, result) = run(cases[3], engine, 4);
        assert!(matches!(result.outcome, Outcome::Unsupported { .. }));
    }
}

