#[test]
fn local_native_xorpd_fixtures_match_independent_literal_and_preserve_state() {
    let cases: [(&[u8], &str); 2] = [
        (
            include_bytes!(
                "../../../tests/fixtures/x86/stage2/s2_40b_xorpd_xmm0_xmm1_asymmetric_a.case.json"
            ),
            "f0e0d0c0b0a090807060504030201000",
        ),
        (
            include_bytes!(
                "../../../tests/fixtures/x86/stage2/s2_40b_xorpd_xmm0_xmm1_asymmetric_b.case.json"
            ),
            "5aa50ff0e1d2c3b4e11ec3f0f00f2d5a",
        ),
    ];
    for (bytes, expected_xmm0) in cases {
        let (input, result) = run(bytes, "interpreter", 0);
        assert_eq!(
            input.fixture.profile,
            od_testkit::v2::Profile::LongNativeXorpdXmm0Xmm1V1
        );
        assert_eq!(count(&result), 1);
        assert!(matches!(result.outcome, Outcome::StopAddress {}));
        let observed = snapshot(&result);
        assert_eq!(observed.state.rip, input.fixture.stop_rip.unwrap());
        assert_eq!(observed.state.gpr, input.fixture.initial_state.gpr);
        assert_eq!(observed.state.rflags, input.fixture.initial_state.rflags);
        assert_eq!(observed.state.sse.as_ref().unwrap().xmm[0], expected_xmm0);
        assert_eq!(observed.state.sse.as_ref().unwrap().mxcsr, HexU64(0x1f80));
        for register in 1..16 {
            assert_eq!(
                observed.state.sse.as_ref().unwrap().xmm[register],
                input.fixture.initial_state.sse.as_ref().unwrap().xmm[register]
            );
        }
        let (_, jit_result) = run(bytes, "jit", 4);
        assert!(matches!(jit_result.outcome, Outcome::Unsupported { .. }));
    }
}

#[test]
fn native_xorpd_handwritten_boundaries_match_raw_byte_oracle() {
    let cases = [
        (
            "s2_42a_hand_zero_ones",
            "00000000000000000000000000000000",
            "ffffffffffffffffffffffffffffffff",
            "ffffffffffffffffffffffffffffffff",
        ),
        (
            "s2_42a_hand_ones_zero",
            "ffffffffffffffffffffffffffffffff",
            "00000000000000000000000000000000",
            "ffffffffffffffffffffffffffffffff",
        ),
        (
            "s2_42a_hand_alternating",
            "55555555555555555555555555555555",
            "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa",
            "ffffffffffffffffffffffffffffffff",
        ),
        (
            "s2_42a_hand_equal",
            "0123456789abcdeffedcba9876543210",
            "0123456789abcdeffedcba9876543210",
            "00000000000000000000000000000000",
        ),
    ];
    let template = Fixture::from_json(include_bytes!(
        "../../../tests/fixtures/x86/stage2/s2_40b_xorpd_xmm0_xmm1_asymmetric_a.case.json"
    ))
    .unwrap()
    .fixture;
    for (case_id, xmm0, xmm1, expected_xmm0) in cases {
        let mut fixture = template.clone();
        fixture.case_id = case_id.into();
        let sse = fixture.initial_state.sse.as_mut().unwrap();
        sse.xmm[0] = xmm0.into();
        sse.xmm[1] = xmm1.into();
        for register in 2..16 {
            sse.xmm[register] = format!("{:02x}", register).repeat(16);
        }
        let bytes = fixture.to_json().unwrap();
        let (loaded, result) = run(&bytes, "interpreter", 0);
        let observed = snapshot(&result);
        let mut oracle = [0; 16];
        let lhs = decode_xmm_literal(xmm0);
        let rhs = decode_xmm_literal(xmm1);
        for index in 0..16 {
            oracle[index] = lhs[index] ^ rhs[index];
        }
        assert_eq!(encode_xmm_literal(&oracle), expected_xmm0);
        assert_eq!(observed.state.sse.as_ref().unwrap().xmm[0], expected_xmm0);
        assert_eq!(observed.state.gpr, loaded.fixture.initial_state.gpr);
        assert_eq!(observed.state.rflags, loaded.fixture.initial_state.rflags);
        assert_eq!(observed.state.rip, loaded.fixture.stop_rip.unwrap());
        assert_eq!(observed.state.sse.as_ref().unwrap().mxcsr, HexU64(0x1f80));
        for register in 1..16 {
            assert_eq!(
                observed.state.sse.as_ref().unwrap().xmm[register],
                loaded.fixture.initial_state.sse.as_ref().unwrap().xmm[register]
            );
        }
        assert_eq!(
            observed.memory[0].bytes_hex,
            loaded.fixture.memory[0].initial_bytes_hex
        );
    }
}

fn decode_xmm_literal(value: &str) -> [u8; 16] {
    let mut bytes = [0; 16];
    for (index, byte) in bytes.iter_mut().enumerate() {
        *byte = u8::from_str_radix(&value[index * 2..index * 2 + 2], 16).unwrap();
    }
    bytes
}

fn encode_xmm_literal(bytes: &[u8; 16]) -> String {
    bytes.iter().map(|byte| format!("{byte:02x}")).collect()
}

#[test]
fn maxsd_unmasked_literal_matrix_validates_independent_results_and_denials() {
    let root =
        std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../tests/fixtures/x86/stage2");
    let mut paths: Vec<_> = fs::read_dir(root)
        .unwrap()
        .map(|entry| entry.unwrap().path())
        .filter(|path| {
            path.file_name()
                .unwrap()
                .to_string_lossy()
                .starts_with("s2_38h_maxsd_")
        })
        .collect();
    paths.sort();
    assert_eq!(
        paths.len(),
        88,
        "literal MAXSD cross-product and outcome fixtures"
    );
    let mut denial_source = None;
    for path in paths {
        let source = fs::read(&path).unwrap();
        let (input, result) = run(&source, "interpreter", 0);
        assert_eq!(
            input.fixture.profile,
            od_testkit::v2::Profile::LongMaxsdUnmaskedDenormalV1
        );
        assert_eq!(
            od_testkit::v2::compare(&input, &result, &result).unwrap(),
            Vec::<String>::new()
        );
        let Observation::Available { value } = &result.snapshot else {
            panic!("snapshot unavailable")
        };
        assert_eq!(
            value.maxsd_unmasked_controls,
            input.fixture.maxsd_unmasked_controls
        );
        if denial_source.is_none() {
            denial_source = Some(source.clone());
        }
        let name = input.fixture.case_id.as_str();
        let expected = match name {
            "s2_38h_maxsd_finite_lhs_max" => Some("0000000000000040"),
            "s2_38h_maxsd_finite_rhs_max" => Some("0000000000000040"),
            "s2_38h_maxsd_equal_finite_source2" => Some("182d4454fb210940"),
            "s2_38h_maxsd_positive_zero_tie_source2" => Some("0000000000000080"),
            "s2_38h_maxsd_negative_zero_tie_source2" => Some("0000000000000000"),
            "s2_38h_maxsd_infinity_lhs_max" | "s2_38h_maxsd_infinity_rhs_max" => {
                Some("000000000000f07f")
            }
            _ => None,
        };
        if let Some(expected_low) = expected {
            assert!(matches!(result.outcome, Outcome::StopAddress {}));
            assert_eq!(
                &value.state.sse.as_ref().unwrap().xmm[0][..16],
                expected_low
            );
            let initial = input.fixture.initial_state.sse.as_ref().unwrap();
            let final_sse = value.state.sse.as_ref().unwrap();
            assert_eq!(&final_sse.xmm[0][16..], &initial.xmm[0][16..]);
            assert_eq!(&final_sse.xmm[1..], &initial.xmm[1..]);
        }
    }
    let source = denial_source.unwrap();
    let (_, jit) = run(&source, "jit", 4);
    assert!(matches!(jit.outcome, Outcome::Unsupported { .. }));
    let (_, native) = run(&source, "native", 4);
    assert!(matches!(native.outcome, Outcome::Unsupported { .. }));

    let (input, result) = run(&source, "interpreter", 0);
    let mut wrong_form = input.fixture.clone();
    wrong_form.memory[0].initial_bytes_hex = "f20f5fc2".into();
    assert!(wrong_form.validate().is_err());
    let mut missing_controls = input.fixture.clone();
    missing_controls.maxsd_unmasked_controls = None;
    assert!(missing_controls.validate().is_err());
    let mut bad_mxcsr = input.fixture.clone();
    bad_mxcsr.initial_state.sse.as_mut().unwrap().mxcsr = HexU64(0x7e50);
    assert!(bad_mxcsr.validate().is_err());
    let mut tampered_controls = result.clone();
    let Observation::Available { value } = &mut tampered_controls.snapshot else {
        panic!("snapshot unavailable")
    };
    value
        .maxsd_unmasked_controls
        .as_mut()
        .unwrap()
        .sse2_available = false;
    assert!(od_testkit::v2::compare(&input, &result, &tampered_controls).is_err());
    let mut tampered_output = result.clone();
    let Observation::Available { value } = &mut tampered_output.snapshot else {
        panic!("snapshot unavailable")
    };
    value.state.sse.as_mut().unwrap().xmm[0].replace_range(..2, "ff");
    assert!(od_testkit::v2::compare(&input, &result, &tampered_output).is_err());
}

#[test]
fn minpd_unmasked_two_lane_cross_product_validates_independent_results_and_denials() {
    let root =
        std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../tests/fixtures/x86/stage2");
    let mut paths: Vec<_> = fs::read_dir(root)
        .unwrap()
        .map(|entry| entry.unwrap().path())
        .filter(|path| {
            path.file_name()
                .unwrap()
                .to_string_lossy()
                .starts_with("s2_38i_minpd_l0_")
        })
        .collect();
    paths.sort();
    assert_eq!(
        paths.len(),
        128,
        "MINPD lane-class x IM x DM x OSXMMEXCPT fixtures"
    );
    let mut denial_source = None;
    let mut representative = None;
    for path in paths {
        let source = fs::read(&path).unwrap();
        let (input, result) = run(&source, "interpreter", 0);
        assert_eq!(
            input.fixture.profile,
            od_testkit::v2::Profile::LongMinpdUnmaskedDenormalV1
        );
        let expected_lanes = input
            .fixture
            .case_id
            .split("_l0_")
            .nth(1)
            .unwrap()
            .split("_im")
            .next()
            .unwrap();
        let expected_lanes: Vec<_> = expected_lanes.split("_l1_").collect();
        let sse = input.fixture.initial_state.sse.as_ref().unwrap();
        let lhs = decode_xmm_literal(&sse.xmm[0]);
        let rhs = decode_xmm_literal(&sse.xmm[1]);
        for lane in 0..2 {
            let offset = lane * 8;
            let operands = [
                u64::from_le_bytes(lhs[offset..offset + 8].try_into().unwrap()),
                u64::from_le_bytes(rhs[offset..offset + 8].try_into().unwrap()),
            ];
            let invalid = operands
                .iter()
                .any(|bits| ((bits >> 52) & 0x7ff) == 0x7ff && bits & ((1u64 << 52) - 1) != 0);
            let denormal = operands
                .iter()
                .any(|bits| ((bits >> 52) & 0x7ff) == 0 && bits & ((1u64 << 52) - 1) != 0);
            let actual = match (invalid, denormal) {
                (false, false) => "n",
                (true, false) => "i",
                (false, true) => "d",
                (true, true) => "id",
            };
            assert_eq!(
                actual, expected_lanes[lane],
                "fixture lane encoding: {}",
                input.fixture.case_id
            );
        }
        assert_eq!(
            od_testkit::v2::compare(&input, &result, &result).unwrap(),
            Vec::<String>::new()
        );
        let Observation::Available { value } = &result.snapshot else {
            panic!("snapshot unavailable")
        };
        assert_eq!(
            value.minpd_unmasked_controls,
            input.fixture.minpd_unmasked_controls
        );
        if denial_source.is_none() {
            denial_source = Some(source.clone());
        }
        if representative.is_none() {
            representative = Some((input.clone(), result.clone()));
        }
    }
    let root =
        std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../tests/fixtures/x86/stage2");
    let mut special_paths: Vec<_> = fs::read_dir(root)
        .unwrap()
        .map(|entry| entry.unwrap().path())
        .filter(|path| {
            path.file_name()
                .unwrap()
                .to_string_lossy()
                .starts_with("s2_38i_minpd_special_")
        })
        .collect();
    special_paths.sort();
    assert_eq!(
        special_paths.len(),
        16,
        "MINPD NaN, selector, signed-zero and sticky-only literals"
    );
    for path in special_paths {
        let source = fs::read(path).unwrap();
        let (input, result) = run(&source, "interpreter", 0);
        assert_eq!(
            input.fixture.profile,
            od_testkit::v2::Profile::LongMinpdUnmaskedDenormalV1
        );
        assert_eq!(
            od_testkit::v2::compare(&input, &result, &result).unwrap(),
            Vec::<String>::new()
        );
        let Observation::Available { value } = &result.snapshot else {
            panic!("snapshot unavailable")
        };
        let expected_xmm0 = match input.fixture.case_id.as_str() {
            "s2_38i_minpd_special_masked_qnan_source2_lane0" => {
                Some("452301efcdabf8ff000000000000f03f")
            }
            "s2_38i_minpd_special_masked_snan_source2_lane1" => {
                Some("000000000000f03f98badcfe3412f07f")
            }
            "s2_38i_minpd_special_masked_qnan_source1_lane0" => {
                Some("0000000000000040000000000000f03f")
            }
            "s2_38i_minpd_special_masked_snan_source1_lane1" => {
                Some("000000000000f03f0000000000000040")
            }
            "s2_38i_minpd_special_positive_zero_tie_source2" => {
                Some("00000000000000800000000000000000")
            }
            "s2_38i_minpd_special_negative_zero_tie_source2" => {
                Some("00000000000000000000000000000080")
            }
            "s2_38i_minpd_special_equal_finite_source2" => Some("0921fb54442df83f0921fb54442df83f"),
            "s2_38i_minpd_special_infinity_lhs_min" | "s2_38i_minpd_special_infinity_rhs_min" => {
                Some("000000000000f0ff000000000000f03f")
            }
            _ => None,
        };
        if let Some(expected) = expected_xmm0 {
            assert_eq!(
                value.state.sse.as_ref().unwrap().xmm[0],
                expected,
                "literal MINPD result bits: {}",
                input.fixture.case_id
            );
        }
    }
    let source = denial_source.unwrap();
    let (_, jit) = run(&source, "jit", 4);
    assert!(matches!(jit.outcome, Outcome::Unsupported { .. }));
    let (_, native) = run(&source, "native", 4);
    assert!(matches!(native.outcome, Outcome::Unsupported { .. }));
    let (input, result) = representative.unwrap();
    let mut missing_controls = input.fixture.clone();
    missing_controls.minpd_unmasked_controls = None;
    assert!(missing_controls.validate().is_err());
    let mut wrong_form = input.fixture.clone();
    wrong_form.memory[0].initial_bytes_hex = "f20f5dc1".into();
    assert!(wrong_form.validate().is_err());
    let mut bad = result.clone();
    let Observation::Available { value } = &mut bad.snapshot else {
        panic!("snapshot unavailable")
    };
    value
        .minpd_unmasked_controls
        .as_mut()
        .unwrap()
        .cr4_osxmmexcpt = !value.minpd_unmasked_controls.unwrap().cr4_osxmmexcpt;
    assert!(od_testkit::v2::compare(&input, &result, &bad).is_err());
    let mut bad_state = result.clone();
    let Observation::Available { value } = &mut bad_state.snapshot else {
        panic!("snapshot unavailable")
    };
    value.state.sse.as_mut().unwrap().xmm[0].replace_range(..2, "ff");
    assert!(od_testkit::v2::compare(&input, &result, &bad_state).is_err());
}

