    fixture.cvtsi2sd_r32_controls = None;
    fixture.cvtsi2sd_r64_controls = None;
    fixture.cvtsi2ss_controls = Some(od_testkit::v2::Cvtsi2ssControlSnapshot {
        sse_available: true,
        cr0_em: false,
        cr0_ts: false,
        cr4_osfxsr: true,
        cr4_osxmmexcpt: true,
    });
    fixture.initial_state.sse.as_mut().unwrap().mxcsr = HexU64(0x1f80);
